//! 🧬️ Logical scoped children forward into one original decoder ledger and an explicit empty recipient.
use super::{NativeDecodeControl,NativeDecodeProgress,NativeDecodeRetirementRecipient};
use crate::{ErasedSnapshotRetirement,ValueError,ValueRefusalKind};
struct Scope<'owner,'call>{control:NativeDecodeControl<'call>,maximum:&'owner mut usize,scope_maximum:&'owner mut Option<usize>,owned:&'owner mut usize,completed:&'owner mut usize,total:&'owner mut usize,started:&'owner mut bool,stage:&'owner mut u64,depth:&'owner mut usize,work_actual:&'owner mut u64,work_reserved:&'owner mut u64,work_reserved_issuer:&'owner mut Option<u64>,work_reserved_action:&'owner mut Option<u64>,work_quote_pending:&'owner mut bool}
impl Drop for Scope<'_, '_>{fn drop(&mut self){*self.maximum=self.control.maximum_bytes;*self.scope_maximum=self.control.scope_maximum;*self.owned=self.control.owned_bytes;*self.completed=self.control.completed;*self.total=self.control.total;*self.started=self.control.started;*self.stage=self.control.stage;*self.depth=self.control.depth;*self.work_actual=self.control.work.actual;*self.work_reserved=self.control.work.reserved;*self.work_reserved_issuer=self.control.work.reserved_issuer;*self.work_reserved_action=self.control.work.reserved_action;*self.work_quote_pending=self.control.work.quote_pending;self.control.work.reserved=0;self.control.work.reserved_issuer=None;self.control.work.reserved_action=None;self.control.work.quote_pending=false;}}
pub(super) fn run<T,E:From<ValueError>>(original:&mut NativeDecodeControl<'_>,recipient:&mut NativeDecodeRetirementRecipient,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->Result<T,E>)->Result<T,E>{
 if !original.retirement.as_ref().is_some_and(|parent|parent.reserved)||!recipient.terminal_is_empty(){return Err(E::from(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native child needs an active parent slot and an empty original recipient")));}
 let callback:&mut dyn FnMut(NativeDecodeProgress)->bool=&mut *original.callback;
 let mut forwarded=match &mut original.allocation{super::allocation::Binding::Local=>None,super::allocation::Binding::Forwarded(port)=>Some(port.reborrow())};
 let mut construction=original.construction.as_mut().map(|loan|loan.reborrow());
 let mut work_loan=original.work.recipient.as_mut().map(|loan|loan.reborrow());
 let control=NativeDecodeControl{work:super::work::Work{actual:original.work.actual,baseline:original.work.baseline,reserved:original.work.reserved,reserved_issuer:original.work.reserved_issuer,reserved_action:original.work.reserved_action,quote_pending:original.work.quote_pending,recipient:work_loan.as_mut()},scope_maximum:original.scope_maximum,construction:construction.as_mut(),receiving:original.receiving,maximum_bytes:original.maximum_bytes,owned_bytes:original.owned_bytes,completed:original.completed,total:original.total,started:original.started,stage:original.stage,depth:original.depth,ledger:original.ledger,callback,retirement:Some(recipient),allocation:match forwarded.as_mut(){Some(port)=>super::allocation::Binding::Forwarded(port),None=>super::allocation::Binding::Local}};
 let mut scope=Scope{control,maximum:&mut original.maximum_bytes,scope_maximum:&mut original.scope_maximum,owned:&mut original.owned_bytes,completed:&mut original.completed,total:&mut original.total,started:&mut original.started,stage:&mut original.stage,depth:&mut original.depth,work_actual:&mut original.work.actual,work_reserved:&mut original.work.reserved,work_reserved_issuer:&mut original.work.reserved_issuer,work_reserved_action:&mut original.work.reserved_action,work_quote_pending:&mut original.work.quote_pending};
 operation(&mut scope.control)
}
